head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > checkboxLabelPosition]<br/>inputType='checkbox' 인 Column 에 라벨 텍스트가 표시될 위치를 설정합니다.",
    "validation" : [
        "Column 의 checkboxLabel, checkboxLabelColumn, checkboxLabelFormatter 속성으로 라벨 텍스트가 표시되는 경우 동작합니다.",
        "left 설정 시, 라벨 텍스트를 체크박스 왼쪽에 표시합니다.",
        "right 설정 시, 라벨 텍스트를 체크박스 오른쪽에 표시합니다.",
        "미설정 시, 라벨 텍스트를 체크박스 오른쪽에 표시합니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (검증 대상 속성만 의미 있는 값으로 초기 선택)
    con_checkboxLabelPosition.setValue("left");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - checkboxLabelPosition 은 Header(column3) 와 Body(chk) 의 checkbox Column 양쪽에 고정 적용
//  - 라벨 표시 수단은 전제 조건 : Header 는 checkboxLabel 만 지원하므로 checkboxLabel 선택 시에만 Header 에도 적용
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Header 는 라벨 표시 수단이 checkboxLabel 일 때만 라벨 표시 (checkboxLabelColumn / checkboxLabelFormatter 는 Body 전용)\n[확인] 재생성 직후 결과창의 Header / Body 라벨 위치와 화면상 라벨-체크박스 좌우 배치"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cPosition = con_checkboxLabelPosition.getValue();
    let cLabelProp = con_labelProperty.getValue();

    let attrPosition = (cPosition === '') ? '' : ' checkboxLabelPosition="' + cPosition + '"';
    let attrHeaderLabel = '';
    let attrBodyLabel = '';
    if (cLabelProp === 'checkboxLabel') {
        attrHeaderLabel = ' checkboxLabel="전체 선택"';
        attrBodyLabel = ' checkboxLabel="선택"';
    } else if (cLabelProp === 'checkboxLabelColumn') {
        attrBodyLabel = ' checkboxLabelColumn="product"';
    } else if (cLabelProp === 'checkboxLabelFormatter') {
        attrBodyLabel = ' checkboxLabelFormatter="scwin.chk_labelFormatter"';
    }

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="product" name="product" dataType="text"></w2:column>';
    strDlt += '<w2:column id="price" name="price" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "product" : "노트북", "price" : "1,250,000", "chk" : "0" },
        { "product" : "모니터", "price" : "320,000", "chk" : "1" },
        { "product" : "키보드", "price" : "89,000", "chk" : "0" },
        { "product" : "마우스", "price" : "45,000", "chk" : "1" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:460px;height:210px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="가격"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="checkbox" id="column3" value=""' + attrHeaderLabel + attrPosition + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="product" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="price" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="checkbox" id="chk" value=""' + attrBodyLabel + attrPosition + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 1 ~ 4 : 재생성 직후 Header / Body 라벨 위치 출력
    setTimeout(function () {
        scwin.printPosition();
    }, 100);
}



// checkboxLabelFormatter 전제용 사용자 정의 함수 : 상품명 뒤에 '담기' 를 붙여 반환
scwin.chk_labelFormatter = function (row, col, checkboxLabel) {
    return dlt_bind.getCellData(row, "product") + " 담기";
}



// 셀(td) 안의 라벨과 체크박스 배치 판정 (DOM 순서 + 화면상 x 좌표)
scwin.getPositionInfo = function (td) {
    let input = td ? td.querySelector("input[type='checkbox']") : null;
    let label = td ? td.querySelector("label") : null;
    if (!input || !label) {
        return { text : "", pos : input ? "라벨 없음" : "체크박스 없음" };
    }
    let domLeft = (label.compareDocumentPosition(input) & Node.DOCUMENT_POSITION_FOLLOWING) ? true : false;
    let labelX = Math.round(label.getBoundingClientRect().left);
    let inputX = Math.round(input.getBoundingClientRect().left);
    let screenLeft = labelX < inputX;
    let strPos = (domLeft === screenLeft) ? (screenLeft ? "체크박스 왼쪽" : "체크박스 오른쪽") : "DOM 순서와 화면 위치 불일치";
    return {
        text : "'" + label.textContent + "'",
        pos : strPos + " (DOM " + (domLeft ? "label -> input" : "input -> label") + ", 라벨 위치 " + labelX + "px / 체크박스 위치 " + inputX + "px)"
    };
}



// validation 1 ~ 4 : Header / Body 라벨 위치 출력
scwin.printPosition = function () {
    let headerTd = document.querySelector("#" + target1.id + "_column3");
    let hInfo = scwin.getPositionInfo(headerTd);
    wf_body_bottom.getObj("scwin").setReturnValue("Header : " + (hInfo.text ? hInfo.text + " " : "") + hInfo.pos);

    // Body 는 모든 행의 배치가 같으면 1줄로 묶고, 다르면 행별로 출력
    let arrText = [];
    let arrPos = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_2']");
        let info = scwin.getPositionInfo(td);
        arrText.push(info.text);
        arrPos.push(info.pos);
    }
    let samePos = arrPos.every(function (pos) { return pos === arrPos[0]; });
    let strBody = "";
    if (samePos) {
        strBody = (arrText[0] ? arrText.join(", ") + " 모두 " : "모든 행 ") + arrPos[0];
    } else {
        strBody = arrPos.map(function (pos, i) { return i + "행 " + arrText[i] + " " + pos; }).join(" / ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("Body : " + strBody);
}
